-- 7) Confere e corrige: "Centrimóveis" e coisas do Rio só podem aparecer na turma do Rio.
-- Inclui o ajuste 06 (aulas por cidade). Pode rodar mais de uma vez.

-- ===== Ajuste 06: aulas por cidade =====
-- 6) Conteúdo das aulas por cidade: o texto geral fica neutro (sem nomes do Rio) e a turma do Rio
-- mantém os seus docentes e a legislação carioca. Pode rodar mais de uma vez.

alter table public.aulas add column if not exists por_turma jsonb not null default '{}'::jsonb;

