-- Parceiro certo em cada turma
update public.turmas set parceiro = 'Condohuby' where id = 'sp-2027' and (parceiro is null or parceiro ~* 'centrim');
update public.turmas set parceiro = 'A definir' where id in ('poa-2027') and (parceiro is null or parceiro ~* 'centrim');
update public.turmas set nome = 'Turma São Paulo 2027' where id = 'sp-2027' and nome ~* '(rio de janeiro|centrim)';
update public.turmas set nome = 'Turma Curitiba 2027' where id = 'cwb-2027' and nome ~* '(rio de janeiro|centrim)';
update public.turmas set nome = 'Turma Porto Alegre 2027' where id = 'poa-2027' and nome ~* '(rio de janeiro|centrim)';

-- Agenda, tarefas e avisos das outras cidades: tira o que veio do Rio
update public.encontros set detalhe = null where turma_id <> 'rj-2027' and detalhe ~* '(centrim|rio de janeiro|carioca)';
update public.tarefas set descricao = regexp_replace(descricao, '\s*\(?\s*Centrim[óo]veis\s*\)?', '', 'gi')
  where turma_id <> 'rj-2027' and descricao ~* 'centrim';
update public.avisos set texto = 'As datas desta turma ainda serão confirmadas. Assim que estiverem definidas, a agenda aparece aqui.'
  where turma_id <> 'rj-2027' and (texto ~* '(centrim|24/02/2027|rio de janeiro)' or titulo ~* 'centrim');

-- Conferência final: a lista abaixo deve vir VAZIA
select 'turma' as onde, id::text as item, nome || ' · ' || coalesce(parceiro,'') as texto from public.turmas
  where id <> 'rj-2027' and (nome || ' ' || coalesce(parceiro,'')) ~* '(centrim|rio de janeiro)'
union all
select 'agenda ' || turma_id, titulo, coalesce(detalhe,'') from public.encontros
  where turma_id <> 'rj-2027' and (titulo || ' ' || coalesce(detalhe,'')) ~* '(centrim|rio de janeiro|carioca)'
union all
select 'tarefa ' || turma_id, titulo, coalesce(descricao,'') from public.tarefas
  where turma_id <> 'rj-2027' and (titulo || ' ' || coalesce(descricao,'')) ~* '(centrim|rio de janeiro|carioca)'
union all
select 'aviso ' || turma_id, titulo, coalesce(texto,'') from public.avisos
  where turma_id <> 'rj-2027' and (titulo || ' ' || coalesce(texto,'')) ~* '(centrim|rio de janeiro|carioca)'
union all
select 'material', titulo, coalesce(turma_id,'todas as turmas') from public.materiais
  where coalesce(turma_id,'') <> 'rj-2027' and titulo ~* '(centrim|rio de janeiro|carioca)';
